// (fd|fs): 600 outputs, 16 threads x 16 quartets per block, g_size 75
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip1_gen_3230(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 16;
    constexpr int gout_stride = 16;
