                int i = n % 10;
                int j = n / 10 % 6;
                int k = n / 60 % 3;
                int l = n / 180;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _li = _l*nao+_i;
                int _ki = _k*nao+_i;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_li] + dm[_jl] * dm[_ki]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*16] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 540; n+=16) {
                int i = n % 10;
                int j = n / 10 % 6;
                int k = n / 60 % 3;
                int l = n / 180;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _li = _l*nao+_i;
                int _ki = _k*nao+_i;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm [_jk] * dm [_li] + dm [_jl] * dm [_ki] +
                                         dmb[_jk] * dmb[_li] + dmb[_jl] * dmb[_ki]);
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*16] = fac_sym * dd;
            }
