                    v_jz += (aj2 * (vgx[5344] - zjzi * vgx[5312]) - 2 * vgx[5184]) * s;
                    v_kz += (ak2 * vgx[5696] - 1 * vgx[4928]) * s;
                    v_lz += (al2 * (vgx[5696] - zlzk * vgx[5312])) * s;
                    s = dd_cache[10336] * (vgx[0] * vgx[2304]);
                    v_iz += (ai2 * vgx[6496] - 2 * vgx[6432]) * s;
                    v_jz += (aj2 * (vgx[6496] - zjzi * vgx[6464]) - 2 * vgx[6336]) * s;
                    v_kz += (ak2 * vgx[6848] - 1 * vgx[6080]) * s;
                    v_lz += (al2 * (vgx[6848] - zlzk * vgx[6464]) - 1 * vgx[5312]) * s;
