                    s += dd[5] * (g[6] * g[37]);
                    s += dd[21] * (g[1] * g[42]);
                    s += dd[23] * (g[0] * g[43]);
                    v_iy += (ai2 * g[22]) * s;
                    v_jy += (aj2 * (g[22] - yjyi * g[21]) - 1 * g[18]) * s;
                    v_ky += (ak2 * g[27]) * s;
                    v_ly += (al2 * (g[27] - ylyk * g[21])) * s;
                    s = dd[12] * (g[1] * g[36]);
                    s += dd[14] * (g[0] * g[37]);
                    v_iy += (ai2 * g[28]) * s;
                    v_jy += (aj2 * (g[28] - yjyi * g[27]) - 1 * g[24]) * s;
                    v_ky += (ak2 * g[33] - 1 * g[21]) * s;
                    v_ly += (al2 * (g[33] - ylyk * g[27])) * s;
                    s = dd[1] * (g[9] * g[36]);
                    s += dd[7] * (g[6] * g[39]);
                    s += dd[19] * (g[3] * g[42]);
                    s += dd[25] * (g[0] * g[45]);
                    v_iy += (ai2 * g[20] - 1 * g[18]) * s;
                    v_jy += (aj2 * (g[20] - yjyi * g[19])) * s;
                    v_ky += (ak2 * g[25]) * s;
                    v_ly += (al2 * (g[25] - ylyk * g[19])) * s;
                    s = dd[10] * (g[3] * g[36]);
                    s += dd[16] * (g[0] * g[39]);
                    v_iy += (ai2 * g[26] - 1 * g[24]) * s;
                    v_jy += (aj2 * (g[26] - yjyi * g[25])) * s;
                    v_ky += (ak2 * g[31] - 1 * g[19]) * s;
                    v_ly += (al2 * (g[31] - ylyk * g[25])) * s;
                    s = dd[4] * (g[6] * g[36]);
                    s += dd[22] * (g[0] * g[42]);
                    v_iy += (ai2 * g[23] - 1 * g[21]) * s;
                    v_jy += (aj2 * (g[23] - yjyi * g[22]) - 1 * g[19]) * s;
                    v_ky += (ak2 * g[28]) * s;
                    v_ly += (al2 * (g[28] - ylyk * g[22])) * s;
                    s = dd[13] * (g[0] * g[36]);
                    v_iy += (ai2 * g[29] - 1 * g[27]) * s;
                    v_jy += (aj2 * (g[29] - yjyi * g[28]) - 1 * g[25]) * s;
                    v_ky += (ak2 * g[34] - 1 * g[22]) * s;
                    v_ly += (al2 * (g[34] - ylyk * g[28])) * s;
                    s = dd[0] * (g[10] * g[18]);
                    s += dd[1] * (g[9] * g[19]);
                    s += dd[3] * (g[7] * g[21]);
                    s += dd[4] * (g[6] * g[22]);
                    s += dd[9] * (g[4] * g[24]);
                    s += dd[10] * (g[3] * g[25]);
                    s += dd[12] * (g[1] * g[27]);
                    s += dd[13] * (g[0] * g[28]);
