            double *dmb = dm;
            dd[0] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+0)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[1] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+1)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[2] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+2)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[3] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+3)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[4] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+4)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[5] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+5)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[6] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+0)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[7] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+1)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[8] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+2)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[9] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+3)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+3)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[10] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+4)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+4)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[11] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+5)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+5)] * dm[(l0+0)*nao+(k0+1)] : 0.));
            dd[12] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+0)] * dm[(l0+0)*nao+(k0+2)] : 0.));
            dd[13] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+1)] * dm[(l0+0)*nao+(k0+2)] : 0.));
            dd[14] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+2)] * dm[(l0+0)*nao+(k0+2)] : 0.));
            dd[15] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+3)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+3)] * dm[(l0+0)*nao+(k0+2)] : 0.));
            dd[16] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+4)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+4)] * dm[(l0+0)*nao+(k0+2)] : 0.));
